const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd, numpy as np
from rdkit import Chem, RDLogger
from rdkit.Chem import AllChem
from rdkit.ML.Cluster import Butina
RDLogger.DisableLog('rdApp.*')
for name in ['bbbp','tox21']:
 d=pd.read_csv('/app/data/'+name+'_train.csv')
 fps=[]
 for s in d.smiles:
  m=Chem.MolFromSmiles(s)
  if m is None: m=Chem.MolFromSmiles(s,sanitize=False)
  fps.append(AllChem.GetMorganGenerator(radius=2,fpSize=1024).GetFingerprint(m))
 from rdkit import DataStructs
 n=len(fps); ds=[]
 for i in range(1,n): ds.extend([1-x for x in DataStructs.BulkTanimotoSimilarity(fps[i],fps[:i])])
 for cutoff in [.5,.6,.7,.75,.8]:
  cs=Butina.ClusterData(ds,n,cutoff,isDistData=True,reordering=True)
  sizes=sorted([len(x) for x in cs],reverse=True)
  print(name,cutoff,'clusters',len(cs),'top',sizes[:10],'single',sum(x==1 for x in sizes))
PY",workdir:"/app",yield_time_ms:30000,max_output_tokens:10000});
text(r.output);

